           \if\next L\mkern-\@ne mu\else
            \if\next M\mkern-\@ne mu\else
             \if\next N\mkern-0.5mu\else
              \if\next P\mkern-\@ne mu\else
               \if\next X\mkern-\@ne mu\else
                \if\next \rho\mkern-1.5mu\else
                 \if\next \mu\mkern-1 mu\else
                 \fi
                \fi
               \fi%
              \fi%
             \fi%
            \fi%
           \fi%
          \fi%
         \fi%
        \fi%
       \fi%
      \fi%
     \fi%
    \fi%
   \fi%
  \fi%
 \fi}
